INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23471$nota-0048$m23471$, $m23472$Training and Racing with a Power Meter.pdf$m23472$, $m23473$121$m23473$, $m23474$set your power meter on the smallest sampling interval you can... set your power display to show your three-second-average power... Make sure that you zero the power meter before you begin.$m23474$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23475$nota-0048$m23475$, $m23476$Training and Racing with a Power Meter.pdf$m23476$, $m23477$121$m23477$, $m23478$When you view your ride graphs, either look at the data without any smoothing or with just five-second smoothing... In five-second smoothing, the data are smoothed over five-second time periods. This is short enough that you lose little of the meaning contained in the data.$m23478$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23479$nota-0048$m23479$, $m23480$nota-0012$m23480$, $m23481$complementa$m23481$, $m23482$reforça a recomendação de taxa de amostragem máxima do Capítulo 2, agora do ponto de vista de preparar os dados para análise$m23482$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23483$nota-0048$m23483$, $m23484$nota-0015$m23484$, $m23485$pre-requisito$m23485$, $m23486$antes de analisar, remover os mesmos picos espúrios descritos na nota-0015$m23486$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23487$nota-0050$m23487$, $m23488$Training and Racing with a Power Meter.pdf$m23488$, $m23489$124$m23489$, $m23490$say that in January your FTP was 200 watts. This would mean that your Tempo level (Level 3, 76–90 percent of FTP) would be between 152 and 180 watts. ... By June, however, you may have raised your FTP to 260 watts. Your corresponding Level 3 watts will now be 197–234.$m23490$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23491$nota-0050$m23491$, $m23492$Training and Racing with a Power Meter.pdf$m23492$, $m23493$124$m23493$, $m23494$Because your fitness has increased so dramatically, 152–180 watts is now in your Level 2, or Endurance level. This is great news. But you will have to adjust your settings, and your training, to make further progress.$m23494$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23495$nota-0050$m23495$, $m23496$nota-0022$m23496$, $m23497$pre-requisito$m23497$, $m23498$usa a tabela de zonas percentuais de FTP da nota-0022, mas alerta que os limites em watts absolutos precisam ser recalculados a cada mudança de FTP$m23498$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23499$nota-0052$m23499$, $m23500$Training and Racing with a Power Meter.pdf$m23500$, $m23501$126$m23501$, $m23502$if you alternated between pedaling for 15 seconds at 400 watts and pedaling for 15 seconds at 100 watts, and kept this up for an entire hour, you would end up spending 30 minutes pedaling at 400 watts, which is a power that you might be able to maintain for only about 4 minutes if you were pedaling at this level continuously.$m23502$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23503$nota-0052$m23503$, $m23504$Training and Racing with a Power Meter.pdf$m23504$, $m23505$126$m23505$, $m23506$This is not an issue when using heart rate, because (1) heart rate lags behind changes in power... very short forays get averaged into the mix... 'time in level' is much more meaningful when applied to heart rate than when applied to power.$m23506$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23507$nota-0052$m23507$, $m23508$nota-0001$m23508$, $m23509$complementa$m23509$, $m23510$mesmo princípio-base: FC tem inércia/defasagem fisiológica que a potência não tem$m23510$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23511$nota-0052$m23511$, $m23512$nota-0016$m23512$, $m23513$complementa$m23513$, $m23514$outra regra sobre como interpretar corretamente médias/distribuições de potência vs. outros sinais$m23514$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23515$nota-0053$m23515$, $m23516$Training and Racing with a Power Meter.pdf$m23516$, $m23517$127$m23517$, $m23518$By plotting your peak power over small slices of time, you can view a telling graph of your mean maximal power. This is quite literally a plot of your best average power for each second of the ride... When you examine maximal power for a relatively large set of data (six months or greater), the shape of the curve will be based on your personal set of abilities.$m23518$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23519$nota-0053$m23519$, $m23520$Training and Racing with a Power Meter.pdf$m23520$, $m23521$127$m23521$, $m23522$the slope of your Mean Maximal Power Curve might be very consistent from 20 seconds out to 2.5 minutes but run at a lower angle from 2.5 minutes out to 25 minutes. This might tell you that at 2.5 minutes your body shifts emphasis from the anaerobic capacity system to the VO2max and lactate systems.$m23522$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23523$nota-0053$m23523$, $m23524$Training and Racing with a Power Meter.pdf$m23524$, $m23525$128$m23525$, $m23526$If you see a distinct hump in the curve at around 3–6 minutes... this indicates your strength at VO2max power. Or, if you see a plateau in the curve, you may have a weakness.$m23526$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23527$nota-0053$m23527$, $m23528$Training and Racing with a Power Meter.pdf$m23528$, $m23529$128$m23529$, $m23530$If you did a workout with 5-minute efforts, and then looked at the watts you produced at 6 minutes, the data may not be indicative of your overall ability. To obtain valid data, you would need to do specific 6-minute efforts.$m23530$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23531$nota-0053$m23531$, $m23532$nota-0037$m23532$, $m23533$pre-requisito$m23533$, $m23534$a MMP Curve é a base de dados real sobre a qual a Power Duration Curve (nota-0037) é ajustada matematicamente$m23534$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23535$nota-0055$m23535$, $m23536$Training and Racing with a Power Meter.pdf$m23536$, $m23537$144$m23537$, $m23538$a match can be defined as an effort in which one goes over threshold power by at least 20 percent and holds it there for at least 1 minute. Of course, burning the proverbial match could involve an effort longer than 1 minute, but as the time period gets longer, the percentage above threshold power would be lower.$m23538$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23539$nota-0055$m23539$, $m23540$Training and Racing with a Power Meter.pdf$m23540$, $m23541$145$m23541$, $m23542$TABLE 6.2 Power Required to \"Burn a Match\" — Time | % of FTP | Power — 1 min. | 120+ | 396; 5 min. | 114-120 | 376-396; 10 min. | 108-114 | 356-376; 20 min. | 100-108 | 330-356 — Note: In this example, the athlete's FTP is 330 watts.$m23542$);
